import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Login.css';
import HomeIcon from '../Common/HomeIcon';
import { login } from '../../services/api';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      alert('Completează toate câmpurile!');
      return;
    }

       try {
      const result = await login({ email, password });

      // !!! IMPORTANT: Ajustați aceste linii conform structurii REALE a răspunsului de la backend-ul de login !!!

      // Presupunând că răspunsul arată ca { token: "...", userId: ..., username: ..., email: ... }
      if (result && result.token && result.userId) {
          localStorage.setItem('token', result.token); // Salvează token-ul corect
          localStorage.setItem('userId', result.userId); // !!! NOU: Salvează ID-ul utilizatorului !!!
          localStorage.setItem('username', result.username || email.split('@')[0]); // Salvează username (foloseste din răspuns sau extrage din email)
          localStorage.setItem('email', result.email || email); // Salvează email (foloseste din răspuns sau din input)

          window.dispatchEvent(new Event('authChange')); // Declanșează evenimentul de schimbare a autentificării
          navigate('/', { replace: true }); // Redirecționează către pagina principală
      } else {
          // Dacă răspunsul nu are structura așteptată, tratează ca eroare
          const errorMessage = result && result.message ? result.message : 'Login failed: Unexpected response from server.';
          setError(errorMessage);
          alert(errorMessage);
      }

    } catch (err) {
      setError(err.message);
      alert(err.message);
    }




  };

  return (
    <div className="login-container">
      <HomeIcon />
      <h1>Login</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="password"
          placeholder="Parolă"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button type="submit">Login</button>

        {error && <p style={{ color: 'red' }}>{error}</p>}

        <p style={{ textAlign: 'center', marginTop: '15px' }}>
          Nu ai un cont? <Link to="/register">Înregistrează-te</Link>
        </p>
      </form>

      {submitted && <p style={{ color: 'green' }}>Te-ai logat cu succes!</p>}
    </div>
  );
}

export default Login;
